const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([157.706220, -34.344553]);
  const roi = point.buffer(100000); // 100km radius

  const period1_start = '2018-11-01';
  const period1_end = '2019-02-28';
  const period2_start = '2019-11-01';
  const period2_end = '2020-02-29';

  // 2. Data Acquisition - Try CAMS first, then fallback to MERRA-2
  let col1 = ee.ImageCollection('ECMWF/CAMS/NRT')
    .filterBounds(roi)
    .filterDate(period1_start, period1_end)
    .select('black_carbon_aerosol_optical_depth_550nm');

  let col2 = ee.ImageCollection('ECMWF/CAMS/NRT')
    .filterBounds(roi)
    .filterDate(period2_start, period2_end)
    .select('black_carbon_aerosol_optical_depth_550nm');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Period 1 (2018-2019) Images: ${size1}`);
  console.log(`Period 2 (2019-2020) Images: ${size2}`);

  // Check if collections are empty
  if (size1 === 0 || size2 === 0) {
    // Try MERRA-2 as fallback
    col1 = ee.ImageCollection('NASA/GSFC/MERRA/aer/2')
      .filterBounds(roi)
      .filterDate(period1_start, period1_end)
      .select('BCSMASS');

    col2 = ee.ImageCollection('NASA/GSFC/MERRA/aer/2')
      .filterBounds(roi)
      .filterDate(period2_start, period2_end)
      .select('BCSMASS');

    const size1_fb = col1.size().getInfo();
    const size2_fb = col2.size().getInfo();

    console.log(`Fallback - Period 1 Images: ${size1_fb}`);
    console.log(`Fallback - Period 2 Images: ${size2_fb}`);

    if (size1_fb === 0 || size2_fb === 0) {
      console.log('No data available for one or both periods.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Calculate mean composites
  const mean1 = col1.mean();
  const mean2 = col2.mean();

  // 4. Check pixel counts
  const count1 = mean1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  const count2 = mean2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  console.log(`Period 1 Valid Pixels: ${count1}`);
  console.log(`Period 2 Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean AOD values
  const val1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  const val2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  console.log(`Period 1 (2018-2019) Mean AOD: ${val1}`);
  console.log(`Period 2 (2019-2020) Mean AOD: ${val2}`);

  // 6. Validation & Final Answer
  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (val1 < 0 || val2 < 0 || val1 > 10 || val2 > 10) {
    console.log('Values outside reasonable AOD range.');
    console.log('<answer>C3</answer>');
    return;
  }

  const increase_pct = ((val2 - val1) / val1 * 100).toFixed(2);
  console.log(`Change: ${increase_pct}%`);

  if (val2 > val1) {
    console.log('Black carbon AOD increased in 2019-2020.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Black carbon AOD did not increase in 2019-2020.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
